INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q6407091', 'Laotian Rebellion', 'The Lao Rebellion of 1826–1828 (also known as Anouvong''s Rebellion) was an attempt by King Anouvong (Xaiya Sethathirath V) of the Kingdom of Vientiane to end the suzerainty of Siam and recreate the former kingdom of Lan Xang. In January 1827 the Lao armies of the kingdoms of Vientiane and Champasak moved south and west across the Khorat Plateau, advancing as far as Saraburi, just three days'' march from the Siamese capital of Bangkok.', 1826, NULL, NULL, 1828, NULL, NULL, 'year', '1826–1828', 43, 'https://en.wikipedia.org/wiki/Lao_rebellion_(1826%E2%80%931828)'),
  ('Q4872904', 'Battle of the Day River', 'The Battle of the Day River (French: bataille du Day) took place between late May and early June 1951, around the Day River Delta in the Gulf of Tonkin. Part of the First Indochina War, the battle was the first conventional campaign of Võ Nguyên Giáp, and saw his Việt Minh People''s Army of Vietnam (VPA) forces tackle the Catholic-dominated region of the Delta in order to break its resistance to communist Việt Minh infiltration.', 1951, 6, 18, NULL, NULL, NULL, 'day', '18 June 1951', 37, 'https://en.wikipedia.org/wiki/Battle_of_the_Day_River'),
  ('Q2095768', 'Operation Lam Son 719', 'Operation Lam Son 719 or 9th Route – Southern Laos Campaign (Vietnamese: Chiến dịch Lam Sơn 719 or Chiến dịch đường 9 – Nam Lào) was a limited-objective offensive campaign conducted in the southeastern portion of the Kingdom of Laos. The campaign was carried out by the armed forces of South Vietnam between 8 February and 25 March 1971, during the Vietnam War.', 1971, 2, 8, 1971, 3, 25, 'day', '8 February 1971 – 25 March 1971', 57, 'https://en.wikipedia.org/wiki/Operation_Lam_Son_719'),
  ('Q4130063', 'Vientiane Treaty', 'The Vientiane Agreement was a cease-fire agreement between the two warring factions in the Laotian Civil War, the Kingdom of Laos and the communist Pathet Lao, signed in Vientiane, the capital of Laos, on 21 February 1973.', 1973, 2, 21, NULL, NULL, NULL, 'day', '21 February 1973', 34, 'https://en.wikipedia.org/wiki/Vientiane_Agreement'),
  ('Q249853', 'Insurgency in Laos', 'The insurgency in Laos is a low-intensity conflict between the Lao People''s Democratic Republic on one side and former members of the Secret Army, Laotian royalists, Hmong fighters, and other highland Laotian ethnic minorities on the other. These groups have faced reprisals from the Lao People''s Army and Vietnam People''s Army for their support of the United States-aligned, anti-communist military campaigns in Laos during the Laotian Civil War, which the insurgency is an extension of itself.', 1975, 12, 2, NULL, NULL, NULL, 'day', '2 December 1975', 51, 'https://en.wikipedia.org/wiki/Insurgency_in_Laos'),
  ('Q796498', 'Third Indochina War', 'The Third Indochina War was a series of interconnected military conflicts among the various communist factions over strategic influence in mainland Southeast Asia after communist victory in South Vietnam, Laos, and Cambodia in 1975. The conflict primarily started due to continued raids and incursions by the Khmer Rouge into Vietnamese territory that they sought to retake.', 1975, 5, 1, 1991, 10, 23, 'day', '1 May 1975 – 23 October 1991', 53, 'https://en.wikipedia.org/wiki/Third_Indochina_War'),
  ('Q150495', '2011 Tarlay earthquake', 'The 2011 Shan earthquake occurred on 24 March in Shan State, Myanmar. The earthquake measured Mw 6.8 and had an epicenter northwest of the border between Myanmar, Thailand and Laos.', 2011, 3, 24, NULL, NULL, NULL, 'day', '24 March 2011', 61, 'https://en.wikipedia.org/wiki/2011_Shan_earthquake'),
  ('Q15075468', 'Lao Airlines Flight 301', 'Lao Airlines Flight 301 was a scheduled domestic passenger flight from Vientiane to Pakse, Laos. On 16 October 2013, the ATR 72-600 aircraft operating the flight crashed into the Mekong River near Pakse, killing all 49 people on board.', 2013, 10, 16, NULL, NULL, NULL, 'day', '16 October 2013', 57, 'https://en.wikipedia.org/wiki/Lao_Airlines_Flight_301');

